using System;using System.IO;using System.Reflection;using System.Drawing;using System.Windows.Forms;
internal static class InstallerSelectionUiRegression {
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();var a=Assembly.Load(File.ReadAllBytes(args[0]));var type=a.GetType("SetupForm",true);var flags=BindingFlags.Instance|BindingFlags.NonPublic;using(var form=(Form)Activator.CreateInstance(type,true)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-30000,-30000);form.Show();Application.DoEvents();var versions=(CheckedListBox)type.GetField("versions",flags).GetValue(form);var install=(Button)type.GetField("install",flags).GetValue(form);if(versions.Items.Count==0||versions.CheckedItems.Count!=versions.Items.Count||!install.Enabled)throw new Exception("Installed compatible versions not selected by default");int total=versions.Items.Count;versions.SetItemChecked(0,false);Application.DoEvents();if(versions.CheckedItems.Count!=total-1)throw new Exception("Version cannot be unchecked");((Button)type.GetField("selectNone",flags).GetValue(form)).PerformClick();Application.DoEvents();if(versions.CheckedItems.Count!=0||install.Enabled)throw new Exception("Empty selection did not disable installation");((Button)type.GetField("selectAll",flags).GetValue(form)).PerformClick();Application.DoEvents();if(versions.CheckedItems.Count!=total||!install.Enabled)throw new Exception("Select all failed");type.GetMethod("CompleteInstallation",flags).Invoke(form,null);Application.DoEvents();
if(install.Visible||versions.Enabled)throw new Exception("Successful installation still exposes install action");
foreach(var field in new[]{"browse","selectAll","selectNone"})if(((Button)type.GetField(field,flags).GetValue(form)).Visible)throw new Exception("Install setup button remains after success");
using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(args[1]);}Console.WriteLine("PASS "+total+" installed compatible products checked by default, individual uncheck, select-none disables install, select-all restores selection; success state hides install/setup actions; UI rendered; no installation performed");}return 0;}
}
